package ru.artem.beforethefall.equipment;
import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.Color;import org.bukkit.Location;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.Particle;import org.bukkit.Sound;import org.bukkit.SoundCategory;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.block.Action;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.Damageable;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.inventory.meta.LeatherArmorMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.scheduler.BukkitTask;import ru.artem.beforethefall.BeforeTheFallPlugin;import java.util.List;
public final class GasMaskManager implements Listener {
 private static final int MAX_DURABILITY=100; private final BeforeTheFallPlugin plugin; private final NamespacedKey marker,filter,filterItem,maskDurability; private BukkitTask task; private int ticks;
 public GasMaskManager(BeforeTheFallPlugin p){plugin=p;marker=new NamespacedKey(p,"gas_mask");filter=new NamespacedKey(p,"filter_ticks");filterItem=new NamespacedKey(p,"replacement_filter");maskDurability=new NamespacedKey(p,"mask_durability");}
 public ItemStack createMask(){ItemStack item=new ItemStack(Material.LEATHER_HELMET);LeatherArmorMeta meta=(LeatherArmorMeta)item.getItemMeta();meta.setColor(Color.fromRGB(42,52,47));meta.setDisplayName(ChatColor.DARK_GREEN+"Противогаз");meta.setCustomModelData(21);meta.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Прочность: 100%",ChatColor.GRAY+"Сменный фильтр: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд",ChatColor.YELLOW+"Надень в слот шлема"));meta.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);meta.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,0);meta.getPersistentDataContainer().set(maskDurability,PersistentDataType.INTEGER,MAX_DURABILITY);item.setItemMeta(meta);return item;}
 public ItemStack createFilter(){ItemStack item=new ItemStack(Material.PAPER);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.GREEN+"Сменный фильтр");meta.setCustomModelData(20);meta.setLore(List.of(ChatColor.GRAY+"Картридж для противогаза",ChatColor.GRAY+"Ресурс: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд"));meta.getPersistentDataContainer().set(filterItem,PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);return item;}
 public boolean isFilter(ItemStack i){if(i==null||!i.hasItemMeta())return false;Byte v=i.getItemMeta().getPersistentDataContainer().get(filterItem,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 public boolean isMask(ItemStack i){if(i==null||!i.hasItemMeta())return false;Byte v=i.getItemMeta().getPersistentDataContainer().get(marker,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 private int filterTicks(ItemStack i){if(!isMask(i))return 0;Integer v=i.getItemMeta().getPersistentDataContainer().get(filter,PersistentDataType.INTEGER);return v==null?0:v;}
 private int durability(ItemStack i){if(!isMask(i))return 0;Integer v=i.getItemMeta().getPersistentDataContainer().get(maskDurability,PersistentDataType.INTEGER);return v==null?MAX_DURABILITY:v;}
 public int remainingSeconds(ItemStack i){return Math.max(0,filterTicks(i)/2);} public int remainingDurability(ItemStack i){return durability(i);}
 private void setFilterTicks(ItemStack i,int value){ItemMeta m=i.getItemMeta();int safe=Math.max(0,value);m.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,safe);updateLore(m,safe,durability(i));i.setItemMeta(m);}
 private void updateLore(ItemMeta m,int f,int d){m.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Прочность маски: "+d+"%",ChatColor.GRAY+"Фильтр: "+f/2+" сек.",d<=50?ChatColor.RED+"Стекло треснуло!":ChatColor.GREEN+"Визор цел"));}
 private void setMaskCondition(Player p,ItemStack mask,int value,boolean fogged){int d=Math.max(0,Math.min(MAX_DURABILITY,value));if(d==0){p.getInventory().setHelmet(null);p.playSound(p.getLocation(),Sound.ENTITY_ITEM_BREAK,SoundCategory.PLAYERS,1f,.75f);p.sendMessage(ChatColor.RED+"Противогаз разрушен! Его нужно изготовить заново.");return;}ItemMeta m=mask.getItemMeta();int old=durability(mask);m.getPersistentDataContainer().set(maskDurability,PersistentDataType.INTEGER,d);int model=d<=50?(fogged?24:22):(fogged?23:21);if(!m.hasCustomModelData()||m.getCustomModelData()!=model)m.setCustomModelData(model);if(old!=d)updateLore(m,filterTicks(mask),d);if(m instanceof Damageable dm)dm.setDamage((int)Math.round(Material.LEATHER_HELMET.getMaxDurability()*(MAX_DURABILITY-d)/(double)MAX_DURABILITY));mask.setItemMeta(m);}
 public boolean isProtected(Player p){ItemStack h=p.getInventory().getHelmet();return isMask(h)&&filterTicks(h)>0&&durability(h)>0;}
 @EventHandler public void onFilterUse(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||(e.getAction()!=Action.RIGHT_CLICK_AIR&&e.getAction()!=Action.RIGHT_CLICK_BLOCK))return;ItemStack held=e.getItem();if(!isFilter(held))return;ItemStack helmet=e.getPlayer().getInventory().getHelmet();if(!isMask(helmet)){e.getPlayer().sendMessage(ChatColor.RED+"Сначала надень противогаз в слот шлема.");e.setCancelled(true);return;}int duration=Math.max(1,plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900));setFilterTicks(helmet,duration*2);if(held.getAmount()>1)held.setAmount(held.getAmount()-1);else e.getPlayer().getInventory().setItemInMainHand(null);e.getPlayer().sendMessage(ChatColor.GREEN+"Фильтр установлен: "+duration/60+" минут защиты.");e.setCancelled(true);}
 public void start(){task=Bukkit.getScheduler().runTaskTimer(plugin,()->{ticks++;for(Player p:Bukkit.getOnlinePlayers()){ItemStack h=p.getInventory().getHelmet();if(!isMask(h))continue;int left=filterTicks(h),d=durability(h);boolean fogged=ticks%8>=4;if(fogged&&ticks%8==4){Location breath=p.getEyeLocation().add(p.getEyeLocation().getDirection().multiply(.28));p.getWorld().spawnParticle(Particle.CLOUD,breath,3,.035,.035,.035,.002);}if(left>0){setFilterTicks(h,left-1);if(ticks%80==0){d--;setMaskCondition(p,h,d,fogged);if(d<=0)continue;}else setMaskCondition(p,h,d,fogged);if(left==1)p.sendMessage(ChatColor.RED+"Фильтр противогаза исчерпан!");}else setMaskCondition(p,h,d,fogged);}},10L,10L);}
 public void stop(){if(task!=null)task.cancel();}
}